def max_sum_increasing_subseq(a, n, index, k):
	dp = [[0 for _ in range(n)] 
			for i in range(n)]
	for i in range(n):
		dp[0][i] = a[0] + a[i] if a[0] < a[i] else a[i]
	for i in range(1, n):
		for j in range(n):
			dp[i][j] = (a[j] + dp[i - 1][i] if a[j] + dp[i - 1][i] > dp[i - 1][j] else dp[i - 1][j]) if a[j] > a[i] and i < j else dp[i - 1][j]
	return dp[index][k]

